contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // The amount sent must be exactly the contract's entire balance (whatever it is).
        require(amount == address(c).balance);
        uint receiverBefore = address(this).balance;
        // Owner (this test contract) sends the full balance to an accepting receiver.
        c.sendTo(address(this), amount); if (__ESBMC_reverted()) return;
        assert(address(c).balance == 0 && address(this).balance == receiverBefore + amount);
    }
    receive() external payable {}
}

